package com.bank.token;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

// Pre-computes a pool of prime secure tokens for National Bank of India.
public class TokenPoolService {
    private static final Logger log = Logger.getLogger(TokenPoolService.class.getName());

    // Returns all prime numbers from 2..n using the Sieve of Eratosthenes.
    public List<Integer> primesUpTo(int n) {
        List<Integer> primes = new ArrayList<>();
        if (n < 2) {
            log.fine(() -> "No primes below 2 for n=" + n);
            return primes;
        }
        boolean[] isPrime = new boolean[n + 1];
        Arrays.fill(isPrime, 2, n + 1, true);   // assume 2..n are prime
        // Cross out multiples of each prime p, starting at p*p.
        for (int p = 2; (long) p * p <= n; p++) {
            if (isPrime[p]) {
                for (int m = p * p; m <= n; m += p) {
                    isPrime[m] = false;          // m is composite
                }
            }
        }
        for (int i = 2; i <= n; i++) {
            if (isPrime[i]) primes.add(i);       // survivors are prime
        }
        log.info(() -> "Built token pool of " + primes.size() + " primes up to " + n);
        return primes;
    }

    // Returns just how many primes exist up to n (capacity planning).
    public int countPrimes(int n) {
        return primesUpTo(n).size();
    }
}
