package com.bank.token;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: pre-compute the prime token pool and report its size.
public class TokenPoolDemo {
    private static final Logger log = Logger.getLogger(TokenPoolDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        TokenPoolService service = new TokenPoolService();

        int limit = 30;   // small limit for the demo
        List<Integer> pool = service.primesUpTo(limit);
        log.info(() -> "Prime token pool up to " + limit + " = " + pool);

        int capacity = service.countPrimes(limit);
        log.info(() -> "Settlement token capacity below " + limit + " = " + capacity);
    }
}
